use super::*;

// -- Error ---------------------------------------------------------------

// `#[derive(hashtrinity::Error)]` — the thiserror-compatible subset (`#[error("...")]`/
// `#[from]`), replacing the hand-written Display/std::error::Error/From<io::Error> impls this
// enum used to carry by hand: the same boilerplate `thiserror` exists to remove, generated by
// hashtrinity's own derive instead of a second dependency.
#[derive(hashtrinity::Error, Debug)]
pub enum Error {
    #[error("I/O: {0}")]
    Io(#[from] io::Error),
    #[error("HTTP: {0}")]
    Http(String),
    #[error("TLS: {0}")]
    Tls(String),
    #[error("URL: {0}")]
    Url(String),
    #[error("parse: {0}")]
    Parse(String),
    #[error("overlay: {0}")]
    Overlay(String),
    #[error("youki: {0}")]
    Youki(String),
}

pub type Result<T> = std::result::Result<T, Error>;
